-- Comentarios do CTN, lote 10 (arts. 209 a 218). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='ctn' and numero between 209 and 218 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(209,'','Significado de "Fazenda Pública"','A expressão "Fazenda Pública", quando empregada na Lei sem qualificação, abrange a Fazenda Pública da União, dos Estados, do Distrito Federal e dos Municípios.'),
(210,'','Contagem dos prazos','Os prazos fixados na Lei ou na legislação tributária serão contínuos, excluindo-se na sua contagem o dia de início e incluindo-se o de vencimento. O parágrafo único dispõe que os prazos só se iniciam ou vencem em dia de expediente normal na repartição em que corra o processo ou deva ser praticado o ato.'),
(211,'','Assistência técnica aos governos estaduais e municipais','Incumbe ao Conselho Técnico de Economia e Finanças, do Ministério da Fazenda, prestar assistência técnica aos governos estaduais e municipais, com o objetivo de assegurar a uniforme aplicação da Lei.'),
(211,'Art. 211-A','Prazo para atualização da legislação sobre moderação sancionatória','O Distrito Federal, os Estados e os Municípios deverão, no prazo de 2 (dois) anos, atualizar a sua legislação tributária e aduaneira para adotar, no mínimo, os critérios previstos no § 5º do art. 142, como forma de implementar moderação sancionatória e dosimetria da penalidade (Lei Complementar n. 236, de 2026).'),
(211,'Art. 211-B','Prazo para atualização da legislação sobre processo administrativo fiscal','A União, o Distrito Federal, os Estados e os Municípios deverão, no prazo de 2 (dois) anos, atualizar a sua legislação tributária e aduaneira para adotar, no mínimo, os critérios previstos nos arts. 208-A a 208-J, como forma de implementar o devido processo legal, a ampla defesa, o duplo grau de jurisdição e o contraditório no âmbito do processo administrativo fiscal (Lei Complementar n. 236, de 2026). O parágrafo único dispõe que a não implementação das disposições do caput acarretará a aplicação do disposto nos arts. 208-A a 208-J, até que sobrevenha legislação específica, a qual deverá adotar, no mínimo, os parâmetros explicitados nesses artigos.'),
(212,'','Consolidação anual da legislação tributária','Os Poderes Executivos federal, estaduais e municipais expedirão, por decreto, dentro de 90 (noventa) dias da entrada em vigor da Lei, a consolidação, em texto único, da legislação vigente relativa a cada um dos tributos, repetindo-se essa providência até o dia 31 de janeiro de cada ano.'),
(213,'','Convênios para alíquota uniforme (norma de 1966)','Os Estados pertencentes a uma mesma região geo-econômica celebrarão entre si convênios para o estabelecimento de alíquota uniforme para o imposto a que se refere o art. 52. O parágrafo único dispõe que os Municípios de um mesmo Estado procederão igualmente, no que se refere à fixação da alíquota de que trata o art. 60. O texto remete a artigos que constam como não vigentes no banco.'),
(214,'','Convênios com os Estados sobre operações de exportação (norma de 1966)','O Poder Executivo promoverá a realização de convênios com os Estados, para excluir ou limitar a incidência do imposto sobre operações relativas à circulação de mercadorias, no caso de exportação para o exterior.'),
(215,'','Reajuste de alíquota em 1967 (norma transitória)','A lei estadual pode autorizar o Poder Executivo a reajustar, no exercício de 1967, a alíquota de imposto a que se refere o art. 52, dentro de limites e segundo critérios por ela estabelecidos. O texto fixa o exercício de 1967 e remete a artigo que consta como não vigente no banco.'),
(216,'','Medidas legislativas do art. 21 da Emenda Constitucional n. 18, de 1965 (norma transitória)','O Poder Executivo proporá as medidas legislativas adequadas a possibilitar, sem compressão dos investimentos previstos na proposta orçamentária de 1967, o cumprimento do disposto no art. 21 da Emenda Constitucional n. 18, de 1965.'),
(217,'','Exigibilidade de contribuições não excluídas pelo CTN','As disposições da Lei, notadamente as dos arts. 17, 74, § 2º, e 77, parágrafo único, bem como a do art. 54 da Lei 5.025, de 10 de junho de 1966, não excluem a incidência e a exigibilidade da "contribuição sindical", denominação que passa a ter o imposto sindical de que tratam os arts. 578 e seguintes da Consolidação das Leis do Trabalho, sem prejuízo do disposto no art. 16 da Lei 4.589, de 1964 (inciso I); das denominadas "quotas de previdência" a que aludem os arts. 71 e 74 da Lei 3.807, de 1960, com as alterações do art. 34 da Lei 4.863, de 1965, que integram a contribuição da União para a previdência social, de que trata o art. 157, item XVI, da Constituição Federal (inciso II, com a anotação "Vide Ato Complementar n. 27, de 1966"); da contribuição destinada a constituir o "Fundo de Assistência" e "Previdência do Trabalhador Rural", de que trata o art. 158 da Lei 4.214, de 1963 (inciso III); da contribuição destinada ao Fundo de Garantia do Tempo de Serviço, criada pelo art. 2º da Lei 5.107, de 1966 (inciso IV); e das contribuições enumeradas no § 2º do art. 34 da Lei 4.863, de 1965, com as alterações decorrentes dos arts. 22 e 23 da Lei 5.107, de 1966, e outras de fins sociais criadas por lei (inciso V). O artigo foi incluído pelo Decreto-lei n. 27, de 1966.'),
(218,'','Vigência do CTN','A Lei entrará em vigor, em todo o território nacional, no dia 1º de janeiro de 1967, revogadas as disposições em contrário, especialmente a Lei n. 854, de 10 de outubro de 1949. O texto traz a anotação de renumeração do art. 217 pelo Decreto-lei n. 27, de 1966.')
) as v(n,t,c,a)
where l.codigo='ctn' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;
